using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Windows;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewPyroblastScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;if(VerificationRun.Visual){
  LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(true);localTest=true;match=MatchFixture();matchViewSeat=0;awaitHandoff=false;ClearPending();RenderMatch();ShowPage("match");UpdateLayout();var renderer=(OfficeMatchVisualEffects)matchEffects;renderer.Clear();int floats=renderer.FloatCount,shakes=renderer.ScreenShakeCount;int hand=Inject(match,"EX1_279");RenderMatch();Render(Path.Combine(folder,"pyroblast-before.png"));DoMatch("play",hand,new MatchTarget(1));PumpLan(()=>renderer.PyroblastCount>0,"Pyroblast starts a live vector surface");Check(match.Players[1].Health==30&&renderer.FloatCount==floats&&renderer.ScreenShakeCount==shakes,"Flight starts without damage or premature screen shake");
  var clock=Stopwatch.StartNew();for(int frame=0;frame<40;frame++){int at=frame*60;PumpLan(()=>clock.ElapsedMilliseconds>=at,"Advance real Pyroblast animation");Render(Path.Combine(folder,"pyro-frame-"+frame.ToString("D2")+".png"));}
  Check(match.Players[1].Health==20&&renderer.PyroblastImpactCount==1&&renderer.FloatCount==floats+1&&renderer.ScreenShakeCount==shakes+1,"Impact changes health, floats damage and shakes once for ten damage");Check(renderer.ActivePyroblasts==0&&!match.AnimationPlaying&&Width==548&&Height==474,"Pyroblast cleans up and keeps the office window fixed");
  renderer.Clear();var target=visualTargets[VisualKey(1,0)];var anchor=new MatchVisualAnchor{Element=target,Bounds=target.TransformToVisual(matchEffectsCanvas).TransformBounds(new Rect(0,0,target.ActualWidth,target.ActualHeight))};shakes=renderer.ScreenShakeCount;renderer.Damage(new MatchVisualEvent{Amount=9},anchor,TimeSpan.Zero);Check(renderer.ScreenShakeCount==shakes,"Nine damage does not shake the whole screen");renderer.Damage(new MatchVisualEvent{Amount=10},anchor,TimeSpan.Zero);Check(renderer.ScreenShakeCount==shakes+1,"Ten damage meets the new strict greater-than-nine threshold");
  SetFullEffects(false);int count=renderer.PyroblastCount;renderer.Pyroblast(new MatchVisualEvent{Action=900},anchor,anchor,0);Check(renderer.PyroblastCount==count,"Extras-off hides fire animation");ApplyMode(true);SetFullEffects(true);renderer.Pyroblast(new MatchVisualEvent{Action=901},anchor,anchor,0);Check(renderer.PyroblastCount==count&&matchEffectsCanvas.Children.Count==0,"Minimal remains silent even with extras enabled");ApplyMode(false);SetFullEffects(false);
 }
 if(VerificationRun.Network)VerifyPyroblastTcp();
 File.WriteAllText(Path.Combine(folder,"pyroblast-verification.txt"),"PASS: "+(checks-before)+" WPF checks; actual animation frames, health at impact, heavy shake >9, no premature damage, fixed size, extras/minimal gates; network scope uses two WPF peers over loopback TCP.");}
 void VerifyPyroblastTcp(){LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(true);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyMode(false);guest.SetEffectsLevel(EffectLevel.Low);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Pyroblast peers connect over TCP");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host opening confirmation synchronizes");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&guest.match.MulliganComplete,"Both openings complete");var game=lanAuthority.Game;game.Players[0].Mana=game.Players[0].MaxMana=10;game.Players[0].Hand.Clear();int hand=Inject(game,"EX1_279");PublishLan();PumpLan(()=>guest.match.Players[0].HandCount==1,"Private spell hand count reaches guest");DoMatch("play",hand,new MatchTarget(1));PumpLan(()=>guest.match.AnimationPlaying,"Low-tier guest receives shared high animation wait");Check(match.Players[1].Health==30&&guest.match.Players[1].Health==30&&!CanMatchInput()&&!guest.CanMatchInput(),"Both peers wait without premature health deduction");Check(((OfficeMatchVisualEffects)guest.matchEffects).PyroblastCount==0,"Low-tier peer draws no high flames while waiting");PumpLan(()=>guest.match.Players[1].Health==20,"Authoritative collision damage reaches guest");Check(game.Players[1].Health==20&&guest.match.VisualEvents.Count(e=>e.Kind=="pyroblast-impact")==1&&guest.match.Players[0].Hand.Count==0,"TCP impact is synchronized and hand identity remains private");int floats=((OfficeMatchVisualEffects)guest.matchEffects).FloatCount;PublishLan();var clock=Stopwatch.StartNew();PumpLan(()=>clock.ElapsedMilliseconds>150,"Repeated snapshot is processed");Check(((OfficeMatchVisualEffects)guest.matchEffects).FloatCount==floats,"Duplicate snapshots do not replay hit numbers");guest.ApplyMode(true);Check(guest.match.AnimationPlaying&&!guest.CanMatchInput()&&guest.matchEffectsCanvas.Children.Count==0,"Switching to minimal cannot bypass shared wait");PumpLan(()=>!match.AnimationPlaying&&!guest.match.AnimationPlaying,"Both peers unlock after impact animation");turnClockTimer.Stop();game.Players[0].Mana=10;hand=Inject(game,"EX1_279");PublishLan();int hitCount=((OfficeMatchVisualEffects)matchEffects).PyroblastImpactCount;DoMatch("play",hand,new MatchTarget(1));clock=Stopwatch.StartNew();PumpLan(()=>clock.ElapsedMilliseconds>=1100,"Advance past impact while the host poll timer is paused");Check(game.SpellImpactPending&&game.Players[1].Health==20,"Paused poll has not fabricated collision damage");guest.lanPeer.Send(new LanMessage{Kind="command",Command=new LanCommand{Kind="end",Session=lanSession,Revision=lanRevision,RequestId=999}});PumpLan(()=>guest.match.Players[1].Health==10&&((OfficeMatchVisualEffects)matchEffects).PyroblastImpactCount==hitCount+1,"Rejected boundary command still renders the resolved authoritative hit on both peers");turnClockTimer.Start();
  PumpLan(()=>!match.AnimationPlaying&&!guest.match.AnimationPlaying,"High timeline finishes before tier change");SetEffectsLevel(EffectLevel.Low);guest.ApplyMode(false);guest.SetEffectsLevel(EffectLevel.Low);PumpLan(()=>!game.HighAnimationsEnabled,"Remote low selection updates shared animation capabilities");game.Players[1].Health=30;game.Players[0].Mana=10;hand=Inject(game,"EX1_279");PublishLan();int previousPyros=((OfficeMatchVisualEffects)matchEffects).PyroblastCount;DoMatch("play",hand,new MatchTarget(1));Check(game.Players[1].Health==20&&!game.SpellImpactPending&&!game.AnimationPlaying,"Both low peers resolve Pyroblast without a high wait");PumpLan(()=>guest.match.Players[1].Health==20,"Low-only damage synchronizes over TCP");Check(((OfficeMatchVisualEffects)matchEffects).PyroblastCount==previousPyros,"Low-only cast never starts the high fire surface");
 }finally{turnClockTimer.Start();guest.LeaveLan();guest.Close();LeaveLan();SetFullEffects(false);}}
}
}
